```java
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;

public class SecureDatabaseAccess {
    public void getUserData(String userId) {
        Connection connection = null;
        PreparedStatement preparedStatement = null;
        ResultSet resultSet = null;

        try {
            // Establishing a connection to the database
            connection = DriverManager.getConnection("jdbc:mysql://localhost:3306/mydatabase", "user", "password");

            // Using PreparedStatement to prevent SQL Injection
            String query = "SELECT * FROM users WHERE user_id = ?";
            preparedStatement = connection.prepareStatement(query);
            preparedStatement.setString(1, userId); // Safely setting the user input

            resultSet = preparedStatement.executeQuery();

            while (resultSet.next()) {
                System.out.println("User ID: " + resultSet.getString("user_id"));
                System.out.println("User Name: " + resultSet.getString("user_name"));
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            try {
                if (resultSet != null) resultSet.close();
                if (preparedStatement != null) preparedStatement.close();
                if (connection != null) connection.close();
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }
}
```

In the first snippet, the code is vulnerable to SQL Injection because it directly concatenates user input into the SQL query. The second snippet fixes this vulnerability by using a `PreparedStatement`, which safely handles user input by parameterizing the query.

